  "idge.stop();\n    }\n  };\n})();\n";

const char *homeassistant_get_app_js(unsigned int *len)
{
  if (len != NULL)
    {
      *len = sizeof(g_homeassistant_app_js) - 1;
    }

  return (const char *)g_homeassistant_app_js;
}
